CREATE TABLE cloud_plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),max_devices INTEGER NOT NULL CHECK(max_devices BETWEEN 1 AND 100),provider_product_id TEXT,provider_offer_id TEXT UNIQUE,checkout_url TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,grace_days INTEGER NOT NULL DEFAULT 0 CHECK(grace_days BETWEEN 0 AND 7),updated_at TEXT NOT NULL, period_days INTEGER NOT NULL DEFAULT 30 CHECK(period_days IN(30,90,365)), device_limit INTEGER CHECK(device_limit BETWEEN 1 AND 1000));
CREATE TABLE cloud_customers(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL DEFAULT '',company TEXT NOT NULL DEFAULT '',blocked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE cloud_licenses(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES cloud_customers(id),plan_id TEXT NOT NULL REFERENCES cloud_plans(id),code_hash TEXT NOT NULL UNIQUE,code_encrypted TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',valid_until TEXT,manual_block INTEGER NOT NULL DEFAULT 0,max_devices INTEGER NOT NULL,provider_subscription_id TEXT UNIQUE,provider_updated_at TEXT,provider_priority INTEGER NOT NULL DEFAULT 0,current_period INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL, paid_until TEXT, trial_days INTEGER NOT NULL DEFAULT 0 CHECK(trial_days IN(0,15,30)), trial_started_at TEXT, trial_installation_hash TEXT, is_permanent INTEGER NOT NULL DEFAULT 0 CHECK(is_permanent IN(0,1)), archived_at TEXT);
CREATE TABLE cloud_devices(id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES cloud_licenses(id),installation_hash TEXT NOT NULL,session_hash TEXT,device_name TEXT NOT NULL,activated_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,revoked_at TEXT,UNIQUE(license_id,installation_hash));
CREATE TABLE cloud_challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used_at TEXT,created_at TEXT NOT NULL,dev_code TEXT);
CREATE TABLE cloud_sessions(token_hash TEXT PRIMARY KEY,customer_id TEXT REFERENCES cloud_customers(id),role TEXT NOT NULL CHECK(role IN ('customer','admin','support')),expires_at TEXT NOT NULL,created_at TEXT NOT NULL, scope_license_id TEXT, scope_installation_hash TEXT, admin_email TEXT);
CREATE TABLE cloud_events(id TEXT PRIMARY KEY,dedupe_key TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,order_id TEXT NOT NULL,subscription_id TEXT,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,locked_until TEXT,error_code TEXT,received_at TEXT NOT NULL,processed_at TEXT);
CREATE TABLE cloud_payments(order_id TEXT PRIMARY KEY,license_id TEXT REFERENCES cloud_licenses(id),customer_id TEXT NOT NULL REFERENCES cloud_customers(id),subscription_id TEXT,event_type TEXT NOT NULL,status TEXT NOT NULL,amount_cents INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'BRL',paid_at TEXT,updated_at TEXT NOT NULL);
CREATE TABLE cloud_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE cloud_outbox(id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES cloud_licenses(id),kind TEXT NOT NULL DEFAULT 'license',status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,locked_until TEXT,error_code TEXT,created_at TEXT NOT NULL,sent_at TEXT,UNIQUE(license_id,kind));
CREATE TABLE cloud_settings(id TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE cloud_companies(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,created_at TEXT NOT NULL);
CREATE TABLE cloud_subscriptions(id TEXT PRIMARY KEY,license_id TEXT REFERENCES cloud_licenses(id),customer_id TEXT NOT NULL REFERENCES cloud_customers(id),plan_id TEXT NOT NULL REFERENCES cloud_plans(id),provider_status TEXT NOT NULL,paid_payments INTEGER NOT NULL,paid_until TEXT,updated_at TEXT NOT NULL);
CREATE TABLE cloud_corporate_offers(plan_id TEXT PRIMARY KEY REFERENCES cloud_plans(id),devices INTEGER NOT NULL CHECK(devices BETWEEN 21 AND 1000),period_days INTEGER NOT NULL CHECK(period_days IN(30,90,365)),price_cents INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('creating','ready','uncertain','failed')),provider_offer_id TEXT UNIQUE,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(devices,period_days));
CREATE TABLE cloud_team_enrollments(code_hash TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES cloud_licenses(id),expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE cloud_trial_invites (
  request_id TEXT NOT NULL,
  email TEXT NOT NULL,
  license_id TEXT NOT NULL REFERENCES cloud_licenses(id),
  delivery_id TEXT NOT NULL REFERENCES cloud_outbox(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY(request_id,email)
);